#[test]
fn percentiles_use_nearest_rank_even_for_short_or_unsorted_runs() {
    assert_eq!(nearest_rank(&mut [99, 1, 4, 3], 50), 3);
    assert_eq!(nearest_rank(&mut [99, 1, 4, 3], 99), 99);
    assert_eq!(nearest_rank(&mut [7], 50), 7);
