    round("bash", { command: "cd /app && go test ./..." }, "--- FAIL: TestA\n    a_test.go:9: want 1 got 2\nFAIL\nExit code 1"),
    round("bash", { command: "cd /app && python run.py | grep foo" }, "Command failed (exit code 1)"),
