/**
 * A mock TinyHumans backend for the life-scenario benchmark, serving the one
 * route the agent's `web_search_tool` needs.
 *
 * ## Why this exists
 *
 * `web_search_tool` is not a local tool: it posts to
 * `/agent-integrations/parallel/search` on the hosted backend, which resolves
 * the query against a paid search provider and bills the caller's team. The
 * benchmark has no session to spend — it runs BYOK inference on an offline
 * local token — so every call came back
 * `SESSION_EXPIRED: backend rejected session token … (401 Invalid token)`.
 *
 * The tool was advertised anyway (`tool spec filter: … web_search_tool`), so
 * the model spent calls discovering that it was dead and then routed around it
 * by hand: in the 2026-09-23 run `baggage-policy` burned two calls on the 401s
 * and then improvised a DuckDuckGo HTML scrape, guessing delta.com paths and
 * collecting four 404s. It reached the 15-call cap with the answer assembled
 * and the requested file unwritten, and graded 0/1.
 *
 * That is a defect in the benchmark rig, not in the product: the run offers a
 * capability its own configuration cannot serve. Removing the tool instead
 * would have been the other kind of dishonest — `baggage-policy` and
 * `fact-check-publish` are *about* finding things on the web.
 *
 * ## What is mocked, and what deliberately is not
 *
 * **Discovery is mocked. Retrieval is not.** This server ranks a fixture
 * corpus (`fixtures/search-index.json`) and returns real, live URLs. The agent
 * still fetches each page over the network with `web_fetch` and still has to
 * read what the page actually says. So `baggage-policy`'s `cites_delta_com`
 * and `states_carryon_dimensions` checks stay honest — what is gone is the
 * search engine the run cannot pay for, not the comprehension being measured.
 *
 * Ranking is deliberately crude (term overlap over title, URL, keywords and
 * excerpt). A cleverer ranker would start deciding the scenario's outcome,
 * which is the grader's job.
 *
 * ## Why it takes over the whole backend base URL
 *
 * `api_url` is the single base every backend caller resolves through
 * (`openhuman_tinyhumans::backend::url::effective_backend_api_url`), so pointing it here is what
 * routes the search. That also catches the other backend calls the run makes
 * and cannot authenticate — `/teams/me/usage`, the Composio toolkit list —
 * which previously logged a 401 per turn. They are answered with benign empty
 * stubs, so the log shows the run's own behaviour rather than a fixed auth
 * failure repeated once a turn. Composio itself is untouched: it is redirected
 * separately to `mock-composio.mjs` by `OPENHUMAN_COMPOSIO_DIRECT_BASE_V*`.
 *
 * Loopback with an ephemeral port is important. `effective_backend_api_url`
 * ignores an `api_url` that looks like an inference endpoint, and
 * `looks_like_local_ai_endpoint` treats loopback as a signal only when it is
 * paired with an LLM-ish port or path — so a bare `http://127.0.0.1:<random>`
 * is passed through as a backend override, which is exactly what this needs.
 *
 * Every unhandled route is recorded and answered 404, so a future capability
 * that starts reaching for the backend shows up in `search-requests.json`
 * rather than failing silently.
 */

import fs from "node:fs";
import http from "node:http";
import path from "node:path";

/** Words too common to carry a topic; dropped before scoring. */
const STOPWORDS = new Set([
  "a",
  "an",
  "and",
  "are",
  "as",
  "at",
  "be",
  "by",
  "current",
  "do",
  "does",
  "for",
  "from",
  "how",
  "i",
  "in",
  "is",
  "it",
  "its",
  "me",
  "my",
  "of",
  "on",
  "or",
  "s",
  "that",
  "the",
  "their",
  "there",
  "they",
  "this",
  "to",
  "was",
  "what",
  "when",
  "where",
  "which",
  "who",
  "will",
  "with",
  "you",
  "your",
]);

/** Lowercase alphanumeric terms, stopwords and one-character noise removed. */
function terms(text) {
  return (text || "")
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((t) => t.length > 1 && !STOPWORDS.has(t));
}

/**
 * Does `term` match document term `h`?
 *
 * Exact, or a shared prefix of at least four characters so "fees" finds "fee"
 * and "baggage" finds "checked-baggage" without dragging in a stemmer. The
 * length floor is what stops a two-character fragment matching most of the
 * corpus.
 */
function termMatches(term, h) {
  if (term === h) return true;
  const shorter = term.length <= h.length ? term : h;
  if (shorter.length < 4) return false;
  return term.startsWith(h) || h.startsWith(term);
}

/**
 * Score one document against the query terms.
 *
 * Fields are weighted by how deliberate a match in them is: an explicit
 * `keywords` entry is curated, a title is the page's own claim about itself,
 * a URL segment is incidental, and an excerpt is the loosest signal of all.
 *
 * Returns the weighted total alongside the count of *distinct* query terms
 * that matched anywhere, because the two answer different questions: the total
 * orders the hits, and the distinct count is what tells an off-topic query
 * apart from a weak one. Scoring alone cannot — a single incidental term
 * repeated across four fields outscores a genuine two-term match — and a
 * search that always returns something would send the agent off to fetch
 * pages that have nothing to do with the task.
 */
function score(doc, queryTerms) {
  const fields = [
    [doc.keywords || [], 4],
    [[doc.title || ""], 3],
    [[doc.url || ""], 2],
    [doc.excerpts || [], 1],
  ];
  let total = 0;
  const matched = new Set();
  for (const [values, weight] of fields) {
    const haystack = terms(values.join(" "));
    if (haystack.length === 0) continue;
    for (const term of queryTerms) {
      if (haystack.some((h) => termMatches(term, h))) {
        total += weight;
        matched.add(term);
      }
    }
  }
  return { total, matched: matched.size };
}

/** Load the corpus, tolerating the `_comment` key the fixture carries. */
function loadIndex(indexPath) {
  if (!fs.existsSync(indexPath)) return [];
  const parsed = JSON.parse(fs.readFileSync(indexPath, "utf8"));
  return Array.isArray(parsed) ? parsed : parsed.documents || [];
}

/**
 * Serve the backend routes the benchmark reaches.
 *
 * Resolves once the socket is listening, to `{ url, port, ctx, close }` in the
 * same shape as `startMockComposio` so `run.mjs` handles the two alike.
 */
export function startMockSearch({ indexPath, requestsPath, port = 0 }) {
  const ctx = {
    documents: loadIndex(indexPath),
    /** Every query served, with what it matched — the record a grader or a
     *  post-mortem reads to see whether discovery actually worked. */
    searches: [],
    /** Every request, including the unhandled ones. */
    requests: [],
    flush() {
      if (!requestsPath) return;
      fs.writeFileSync(
        requestsPath,
        JSON.stringify(
          { searches: ctx.searches, requests: ctx.requests },
          null,
          2,
        ),
      );
    },
  };

  const json = (res, code, body) => {
    const payload = JSON.stringify(body);
    res.writeHead(code, {
      "content-type": "application/json",
      "content-length": Buffer.byteLength(payload),
    });
    res.end(payload);
  };

  /**
   * The envelope every backend response is unwrapped from —
   * `integrations/client/errors.rs::parse_envelope` deserializes
   * `{ success, data, error }` and hands back `data`.
   *
   * Returning the bare payload instead fails as `missing field 'success'`, and
   * fails *late*: the tool reports a malformed-response error rather than an
   * empty result, so the agent concludes search is broken and abandons the
   * task. That is exactly what the first run of this mock did, six times over.
   */
  const ok = (res, data) => json(res, 200, { success: true, data });

  const search = (body) => {
    // The core sends Parallel's shape: an `objective` plus `searchQueries`,
    // with the result count under `excerpts.maxResults`.
    const queries = [
      ...(Array.isArray(body.searchQueries) ? body.searchQueries : []),
      body.objective,
      body.query,
    ].filter((q) => typeof q === "string" && q.trim());
    const queryTerms = [...new Set(queries.flatMap(terms))];
    const limit = Math.min(
      Math.max(Number(body?.excerpts?.maxResults) || 5, 1),
      10,
    );

    // An off-topic query must come back empty rather than with the least-bad
    // rows in the corpus: a confidently wrong result set is worse for the
    // agent than none, because it spends fetches on it. Two distinct matching
    // terms is the floor, relaxed to one when the query only has one to give.
    const floor = Math.min(2, queryTerms.length) || 1;
    const ranked = ctx.documents
      .map((doc) => ({ doc, ...score(doc, queryTerms) }))
      .filter((hit) => hit.total > 0 && hit.matched >= floor)
      .sort((a, b) => b.total - a.total || a.doc.url.localeCompare(b.doc.url))
      .slice(0, limit);

    ctx.searches.push({
      at: new Date().toISOString(),
      queries,
      hits: ranked.map((hit) => ({ url: hit.doc.url, score: hit.total })),
    });
    ctx.flush();

    return {
      searchId: `mock-${ctx.searches.length}`,
      // Zero rather than a plausible number: the benchmark's cost column must
      // report what the run actually spent, and this search cost nothing.
      costUsd: 0,
      provider: "LifeScenariosMock",
      results: ranked.map(({ doc }) => ({
        url: doc.url,
        title: doc.title || doc.url,
        publish_date: doc.publish_date ?? null,
        excerpts: doc.excerpts || [],
      })),
    };
  };

  const server = http.createServer((req, res) => {
    const url = new URL(req.url, "http://mock");
    const chunks = [];
    req.on("data", (c) => chunks.push(c));
    req.on("end", () => {
      const raw = Buffer.concat(chunks).toString("utf8");
      let body = {};
      if (raw) {
        try {
          body = JSON.parse(raw);
        } catch {
          body = {};
        }
      }
      const p = url.pathname.replace(/\/+$/, "");
      ctx.requests.push({
        at: new Date().toISOString(),
        method: req.method,
        path: p,
      });

      if (
        p === "/agent-integrations/parallel/search" &&
        req.method === "POST"
      ) {
        try {
          return ok(res, search(body));
        } catch (e) {
          return json(res, 500, {
            success: false,
            data: null,
            error: `mock search failed: ${e.message}`,
          });
        }
      }

      // Benign stubs for the backend calls the run makes but has no session
      // for. Answering them keeps a fixed auth failure out of the log so what
      // remains is the run's own behaviour.
      if (p === "/teams/me/usage" && req.method === "GET") {
        return ok(res, { usage: {}, limits: {}, plan: "life-scenarios-mock" });
      }
      if (p === "/agent-integrations/composio/toolkits") {
        // Empty on purpose: Composio is served by `mock-composio.mjs` over the
        // direct base, so this list must not compete with it.
        return ok(res, { items: [], total_items: 0 });
      }

      ctx.flush();
      return json(res, 404, {
        success: false,
        data: null,
        error: `mock search backend: unhandled ${req.method} ${p}`,
      });
    });
  });

  return new Promise((resolve) => {
    server.listen(port, "127.0.0.1", () => {
      const actual = server.address().port;
      resolve({
        url: `http://127.0.0.1:${actual}`,
        port: actual,
        ctx,
        close: () =>
          new Promise((r) => {
            ctx.flush();
            server.close(r);
          }),
      });
    });
  });
}

/** Where the default corpus lives, for `run.mjs` and the self-test. */
export const DEFAULT_INDEX_PATH = path.join(
  path.dirname(new URL(import.meta.url).pathname),
  "fixtures",
  "search-index.json",
);

/**
 * Behaviour of the life-scenario mock search backend
 * (`life-scenarios/mock-search.mjs`).
 *
 * The rig exists because `web_search_tool` posts to the hosted backend, which
 * the benchmark has no session for — so the tool 401'd on every call and the
 * agent burned its iteration budget routing around it by hand. These lock in
 * the two properties that make the substitute honest: it ranks a corpus of
 * real URLs the agent must still fetch for itself, and it returns nothing at
 * all for a query the corpus does not cover.
 */

import assert from "node:assert/strict";
import test, { after, before } from "node:test";

import {
  DEFAULT_INDEX_PATH,
  startMockSearch,
} from "../life-scenarios/mock-search.mjs";

let server;

before(async () => {
  server = await startMockSearch({ indexPath: DEFAULT_INDEX_PATH, port: 0 });
});

after(async () => {
  await server?.close();
});

/** Post a query the way `WebSearchTool` does. */
async function search(objective, maxResults = 5) {
  const res = await fetch(`${server.url}/agent-integrations/parallel/search`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      objective,
      searchQueries: [objective],
      mode: "fast",
      excerpts: { maxResults, maxCharsPerResult: 500 },
    }),
  });
  assert.equal(res.status, 200);
  const envelope = await res.json();
  // `integrations/client/errors.rs::parse_envelope` deserializes
  // `{ success, data, error }` and returns `data`. A bare payload fails as
  // `missing field 'success'` — and fails late enough to look like a broken
  // tool rather than an empty result, so the agent abandons the task.
  assert.equal(
    envelope.success,
    true,
    "every response must carry the backend envelope",
  );
  return envelope.data;
}

test("the corpus loads past the fixture's _comment key", () => {
  assert.ok(
    server.ctx.documents.length > 0,
    "documents should come from the `documents` array, not the whole object",
  );
});

test("a baggage query ranks delta.com pages first", async () => {
  const body = await search(
    "Delta Air Lines Basic Economy carry-on baggage allowance transatlantic",
  );
  assert.ok(body.results.length > 0, "the corpus covers this query");
  assert.match(body.results[0].url, /(^|\.)delta\.com/);
});

test("a checked-bag fee query surfaces the fee page", async () => {
  const body = await search("Delta checked bag fee first second bag Europe");
  const urls = body.results.map((r) => r.url);
  assert.ok(
    urls.some((u) => /excess-overweight-baggage/.test(u)),
    `expected the fee page among ${JSON.stringify(urls)}`,
  );
});

test("an off-topic query returns nothing rather than the least-bad rows", async () => {
  // A confidently wrong result set is worse than an empty one: the agent
  // spends fetches on it, which is the failure mode this rig removes.
  for (const query of [
    "how do I bake sourdough bread at home",
    "completely unrelated zebra topic",
  ]) {
    const body = await search(query);
    assert.deepEqual(body.results, [], `"${query}" should match nothing`);
  }
});

test("results carry live URLs, so retrieval stays real", async () => {
  const body = await search("Delta baggage overview allowance");
  for (const item of body.results) {
    assert.match(item.url, /^https:\/\//, "every hit must be fetchable");
    assert.ok(item.title, "every hit must carry a title");
  }
});

test("maxResults is honoured and clamped", async () => {
  const body = await search("Delta baggage allowance fees carry-on checked", 2);
  assert.ok(body.results.length <= 2);
});

test("the search is recorded for post-mortems", async () => {
  const before = server.ctx.searches.length;
  await search("Delta baggage overview");
  assert.equal(server.ctx.searches.length, before + 1);
  assert.ok(server.ctx.searches.at(-1).queries.length > 0);
});

test("the cost is reported as zero, because it was", async () => {
  const body = await search("Delta baggage overview");
  assert.equal(body.costUsd, 0);
});

test("the unauthenticated backend calls get benign stubs", async () => {
  // Answered so the core's log shows the run's own behaviour rather than one
  // fixed auth failure repeated every turn. Enveloped like everything else.
  const usage = await fetch(`${server.url}/teams/me/usage`);
  assert.equal(usage.status, 200);
  assert.equal((await usage.json()).success, true);

  const toolkits = await fetch(
    `${server.url}/agent-integrations/composio/toolkits`,
  );
  assert.equal(toolkits.status, 200);
  const body = await toolkits.json();
  assert.equal(body.success, true);
  // Empty on purpose: Composio is served by mock-composio.mjs over the direct
  // base, and a competing list here would shadow it.
  assert.deepEqual(body.data.items, []);
});

test("an unhandled route 404s and is recorded", async () => {
  const res = await fetch(`${server.url}/agent-integrations/something-new`);
  assert.equal(res.status, 404);
  assert.ok(
    server.ctx.requests.some(
      (r) => r.path === "/agent-integrations/something-new",
    ),
    "a capability that starts reaching for the backend must be visible",
  );
});

#!/usr/bin/env node
/**
 * Mock LLM + backend endpoint for the agent-scale benchmark tier.
 *
 * This stands in for `api.tinyhumans.ai` so a NORMALLY-BUILT `openhuman-core`
 * can run real agent turns with no network and no special cargo features. The
 * core reaches it because `config.api_url` (or `BACKEND_URL`) feeds both
 * `effective_api_url` (inference, embeddings) and `effective_backend_api_url`
 * (telemetry), so one base URL captures every backend call a turn makes:
 *
 *   POST /openai/v1/chat/completions   the turn itself (non-streaming)
 *   POST /openai/v1/embeddings         memory recall/write, when it fires
 *   POST /telemetry/langfuse/ingestion after every turn, unless disabled
 *
 * Two properties matter for a benchmark and are worth stating, because both
 * are easy to lose in a later edit:
 *
 * 1. REPLIES ARE DERIVED FROM THE REQUEST, NOT FROM STORED STATE. How deep a
 *    turn is comes from counting `role: "tool"` messages in the body that
 *    arrived. There is no session map, so N concurrent turns cannot interleave
 *    into each other's scripts and the mock holds nothing that grows with load.
 *    The only mutable state is a handful of integer counters.
 *
 * 2. THAT IS ALSO WHAT KEEPS THE MOCK OUT OF THE MEASUREMENT. We are trying to
 *    attribute RSS growth to the core. A mock that retained a request log would
 *    grow too, and (being a separate process) would not show up in the core's
 *    numbers — but it would eventually change the machine's memory pressure and
 *    contaminate the run. Do not add request retention here; if you need to
 *    inspect traffic, add a counter or log to stderr.
 *
 * Usage:
 *   node agent-scale/mock-llm.mjs --port 18700 [options]
 *
 * Options:
 *   --port <n>          listen port. MUST NOT be one of 11434/8000/8080/1234/8888:
 *                       the core classifies those as local-AI endpoints and
 *                       routes around them (see LOCAL_AI_PORTS in crates/openhuman-tinyhumans/src/backend/url.rs).
 *   --latency-ms <n>    mean added latency per completion (default 0)
 *   --jitter-ms <n>     deterministic +/- jitter around that mean (default 0)
 *   --tool-depth <n>    tool calls to emit before the final answer (default 0)
 *   --reply-chars <n>   assistant reply size, to vary serde/alloc pressure (default 240)
 *   --fail-rate <n>     fraction [0,1) of completions answered 500, to exercise
 *                       the core's retry/error path (default 0)
 *   --embed-dims <n>    embedding width (default 1024). MUST match what the
 *                       memory store expects — a mismatch is only a warning,
 *                       and the run silently stores chunks without vectors.
 */

import http from 'node:http';

const LOCAL_AI_PORTS = new Set([11434, 8000, 8080, 1234, 8888]);

// Tools we are willing to drive, most preferred first. Both are read-only and
// cheap, so a deep tool loop stresses the harness rather than the filesystem.
// The mock only ever names a tool the core actually offered in the request, so
// an unknown name here is inert rather than an error.
const TOOL_PREFERENCE = ['memory_search', 'glob'];

/**
 * Background routes the core polls that are not part of a turn.
 *
 * Left un-stubbed these 404, and the core handles that gracefully — but not
 * freely: `/teams/me/usage` routes its 404 through the observability
 * error-reporting path, and the rest log warnings. That is CPU and allocation
 * spent on failure handling rather than on agent work, in a run whose entire
 * purpose is to attribute CPU and allocation. Answering them with empty,
 * well-shaped payloads keeps the process on its normal path.
 *
 * These are counted separately from `unknownRoutes` so the distinction between
 * "deliberately stubbed" and "we did not anticipate this" stays visible.
 */
const ANCILLARY_ROUTES = {
  'GET /teams/me/usage': () => ({
    success: true,
    data: { credits: 1_000_000, used: 0, plan: 'bench' },
  }),
  'GET /agent-integrations/composio/connections': () => ({ success: true, data: [] }),
  'GET /agent-integrations/composio/toolkits': () => ({ success: true, data: [] }),
  'GET /orchestration/v1/sessions': () => ({ success: true, data: [] }),
};

function parseArgs(argv) {
  const opts = {
    port: 18700,
    latencyMs: 0,
    jitterMs: 0,
    toolDepth: 0,
    replyChars: 240,
    failRate: 0,
    embedDims: 1024,
  };
  const numeric = {
    '--port': 'port',
    '--latency-ms': 'latencyMs',
    '--jitter-ms': 'jitterMs',
    '--tool-depth': 'toolDepth',
    '--reply-chars': 'replyChars',
    '--fail-rate': 'failRate',
    '--embed-dims': 'embedDims',
  };
  for (let i = 2; i < argv.length; i += 1) {
    const key = numeric[argv[i]];
    if (!key) throw new Error(`unknown argument: ${argv[i]}`);
    const raw = argv[i + 1];
    i += 1;
    const value = Number(raw);
    if (!Number.isFinite(value)) {
      throw new Error(`${argv[i - 1]} expects a number, got: ${raw}`);
    }
    opts[key] = value;
  }
  if (LOCAL_AI_PORTS.has(opts.port)) {
    throw new Error(
      `--port ${opts.port} is in the transport's LOCAL_AI_PORTS set; the core would ` +
        `treat this as a local-AI endpoint and not route managed inference here. ` +
        `Pick another port.`,
    );
  }
  if (opts.failRate < 0 || opts.failRate >= 1) {
    throw new Error(`--fail-rate must be in [0, 1), got ${opts.failRate}`);
  }
  return opts;
}

/**
 * Deterministic hash of a string, so latency and failure injection are
 * reproducible across runs without a shared RNG (which would be both a lock
 * and a source of cross-request coupling).
 */
function hash32(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i += 1) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

/** Stable [0,1) from a seed. */
function unitFrom(seed) {
  return (hash32(String(seed)) % 1_000_000) / 1_000_000;
}

// Retry counters are keyed by request content. Distinct concurrent turns cannot
// perturb one another, while a retry of the same request still gets a new draw.
const attemptsByRequest = new Map();
const MAX_TRACKED_REQUESTS = 4096;

/** Return the next attempt for a request while bounding benchmark-side state. */
function nextRequestAttempt(requestKey) {
  const attempt = (attemptsByRequest.get(requestKey) ?? 0) + 1;
  // Refresh insertion order so active retrying requests are evicted last.
  attemptsByRequest.delete(requestKey);
  attemptsByRequest.set(requestKey, attempt);
  if (attemptsByRequest.size > MAX_TRACKED_REQUESTS) {
    // Eviction intentionally permits a very old request to restart at attempt
    // 1. Core retries are immediate, so their refreshed keys remain resident;
    // preserving every completed request across an unbounded duration run
    // would make the mock itself accumulate benchmark-distorting state.
    attemptsByRequest.delete(attemptsByRequest.keys().next().value);
  }
  return attempt;
}

const stats = {
  startedAt: Date.now(),
  completions: 0,
  toolCallsEmitted: 0,
  finalAnswers: 0,
  embeddings: 0,
  telemetry: 0,
  ancillary: 0,
  injectedFailures: 0,
  unknownRoutes: 0,
  malformedRequests: 0,
};

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', (chunk) => {
      size += chunk.length;
      // A runaway body would make the mock the memory problem. Cap it.
      if (size > 64 * 1024 * 1024) {
        reject(new Error('request body exceeded 64 MiB'));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function sendJson(res, status, payload) {
  const body = JSON.stringify(payload);
  res.writeHead(status, {
    'content-type': 'application/json',
    'content-length': Buffer.byteLength(body),
  });
  res.end(body);
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Pick a tool to call from the ones the core offered. Returns null when the
 * request carried no tools, which is the correct cue to answer in plain text
 * rather than inventing a call the agent cannot dispatch.
 */
function pickTool(tools) {
  if (!Array.isArray(tools) || tools.length === 0) return null;
  const names = new Set(
    tools.map((t) => t?.function?.name).filter((n) => typeof n === 'string'),
  );
  for (const preferred of TOOL_PREFERENCE) {
    if (names.has(preferred)) return preferred;
  }
  return null;
}

/** Arguments that are valid for the tools we are willing to drive. */
function argumentsFor(toolName) {
  switch (toolName) {
    case 'memory_search':
      return { query: 'benchmark probe' };
    case 'glob':
      return { pattern: '*.md' };
    default:
      return {};
  }
}

// A small vocabulary the reply builder samples from. Replies get stored as
// memories, so if every reply were the same string the whole corpus would
// collapse to one distinct document — fine for throughput, useless for asking
// which memories a retrieval change surfaces.
const VOCAB = [
  'invoice', 'deployment', 'kubernetes', 'roadmap', 'latency', 'onboarding',
  'refund', 'schema', 'migration', 'webhook', 'billing', 'timezone',
  'passport', 'itinerary', 'recipe', 'mortgage', 'vaccination', 'landlord',
  'guitar', 'marathon', 'thesis', 'compiler', 'telescope', 'sourdough',
];

/**
 * Deterministic, varied reply text of approximately `chars` length.
 *
 * `seed` makes it reproducible per turn while still differing between turns.
 */
function buildReplyText(chars, seed) {
  let state = hash32(String(seed)) || 1;
  const next = () => {
    state ^= state << 13;
    state >>>= 0;
    state ^= state >> 17;
    state ^= state << 5;
    state >>>= 0;
    return state;
  };
  const words = [];
  let len = 0;
  while (len < chars) {
    const w = VOCAB[next() % VOCAB.length];
    words.push(w);
    len += w.length + 1;
  }
  return words.join(' ').slice(0, chars);
}

async function handleCompletion(req, res, body, opts) {
  let parsed;
  try {
    parsed = JSON.parse(body);
  } catch {
    stats.malformedRequests += 1;
    sendJson(res, 400, { error: { message: 'invalid JSON body' } });
    return;
  }

  const messages = Array.isArray(parsed.messages) ? parsed.messages : [];
  // Turn depth without stored state: every tool result already in the thread is
  // one tool call we previously emitted.
  const depth = messages.filter((m) => m?.role === 'tool').length;

  // Seed from stable request content so concurrent arrival order cannot change
  // which requests fail or how much latency they receive. Keep a per-content
  // attempt number so retries do not repeat the same injected failure forever.
  const requestKey = String(hash32(body));
  const attempt = nextRequestAttempt(requestKey);
  const seed = `${requestKey}:${attempt}`;

  if (opts.failRate > 0 && unitFrom(`fail:${seed}`) < opts.failRate) {
    stats.injectedFailures += 1;
    sendJson(res, 500, { error: { message: 'injected benchmark failure' } });
    return;
  }

  if (opts.latencyMs > 0 || opts.jitterMs > 0) {
    const offset = opts.jitterMs > 0 ? (unitFrom(`lat:${seed}`) * 2 - 1) * opts.jitterMs : 0;
    await sleep(Math.max(0, opts.latencyMs + offset));
  }

  stats.completions += 1;
  const model = typeof parsed.model === 'string' ? parsed.model : 'mock-model';
  const toolName = depth < opts.toolDepth ? pickTool(parsed.tools) : null;

  let message;
  let finishReason;
  if (toolName) {
    stats.toolCallsEmitted += 1;
    message = {
      role: 'assistant',
      content: null,
      tool_calls: [
        {
          id: `call_bench_${stats.completions}`,
          type: 'function',
          function: {
            name: toolName,
            // The core expects arguments as a JSON *string*.
            arguments: JSON.stringify(argumentsFor(toolName)),
          },
        },
      ],
    };
    finishReason = 'tool_calls';
  } else {
    stats.finalAnswers += 1;
    message = {
      role: 'assistant',
      content: buildReplyText(opts.replyChars, `${seed}:${stats.completions}`),
    };
    finishReason = 'stop';
  }

  // Rough but stable token accounting; the core records usage but does not
  // validate it against the text.
  const promptTokens = Math.max(1, Math.ceil(body.length / 4));
  const completionTokens = Math.max(1, Math.ceil(opts.replyChars / 4));

  sendJson(res, 200, {
    id: `chatcmpl-bench-${stats.completions}`,
    object: 'chat.completion',
    created: Math.floor(Date.now() / 1000),
    model,
    choices: [{ index: 0, message, finish_reason: finishReason }],
    usage: {
      prompt_tokens: promptTokens,
      completion_tokens: completionTokens,
      total_tokens: promptTokens + completionTokens,
    },
  });
}

/**
 * A deterministic pseudo-embedding derived from the input text.
 *
 * Returning one constant vector for every input would be simpler and is what
 * this did first — but it makes every cosine similarity identical, so retrieval
 * ranking becomes degenerate and any experiment about WHICH memories a change
 * surfaces is meaningless. Throughput measurements are unaffected either way
 * (the same work happens whatever the values are), so the flaw is invisible
 * unless you go looking for it.
 *
 * This derives a unit vector from a hash of the text: same text always yields
 * the same vector, similar-but-different texts yield different ones, and the
 * distribution is spread rather than collapsed onto a point. Not semantically
 * meaningful — nothing here models real language — but structurally realistic
 * enough to compare retrieval strategies against each other.
 */
function embeddingFor(text, dims) {
  // xorshift32 seeded by the content hash: cheap, deterministic, no shared state.
  let state = hash32(text) || 1;
  const next = () => {
    state ^= state << 13;
    state >>>= 0;
    state ^= state >> 17;
    state ^= state << 5;
    state >>>= 0;
    return state / 0xffffffff;
  };
  const vec = new Array(dims);
  let norm = 0;
  for (let i = 0; i < dims; i += 1) {
    // Box-Muller-ish spread around zero, so vectors are not all in one orthant.
    const v = next() * 2 - 1;
    vec[i] = v;
    norm += v * v;
  }
  norm = Math.sqrt(norm) || 1;
  for (let i = 0; i < dims; i += 1) vec[i] /= norm;
  return vec;
}

function handleEmbeddings(res, body, opts) {
  stats.embeddings += 1;
  let count = 1;
  let inputs = [''];
  try {
    const parsed = JSON.parse(body);
    if (Array.isArray(parsed.input)) {
      inputs = parsed.input.map((v) => (typeof v === 'string' ? v : JSON.stringify(v)));
      count = Math.max(1, inputs.length);
    } else if (typeof parsed.input === 'string') {
      inputs = [parsed.input];
    }
  } catch {
    stats.malformedRequests += 1;
  }
  // The dimension MUST match what the memory store expects, or every chunk is
  // stored without vectors and the memory write path runs degraded for the whole
  // run — silently, as a warning rather than an error. 1536 (the usual
  // text-embedding-3-small width) is the wrong default here; the store wants
  // 1024.
  sendJson(res, 200, {
    object: 'list',
    model: 'mock-embedding',
    data: Array.from({ length: count }, (_, i) => ({
      object: 'embedding',
      index: i,
      embedding: embeddingFor(inputs[i] ?? '', opts.embedDims),
    })),
    usage: { prompt_tokens: count, total_tokens: count },
  });
}

const opts = parseArgs(process.argv);

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://127.0.0.1:${opts.port}`);
  const path = url.pathname;

  if (req.method === 'GET' && (path === '/health' || path === '/__bench/health')) {
    sendJson(res, 200, { ok: true });
    return;
  }
  if (req.method === 'GET' && path === '/__bench/stats') {
    sendJson(res, 200, { ...stats, uptimeMs: Date.now() - stats.startedAt });
    return;
  }
  if (req.method === 'POST' && path === '/__bench/reset') {
    for (const key of Object.keys(stats)) {
      if (key !== 'startedAt') stats[key] = 0;
    }
    sendJson(res, 200, { ok: true });
    return;
  }

  readBody(req)
    .then(async (body) => {
      if (req.method === 'POST' && path.endsWith('/chat/completions')) {
        await handleCompletion(req, res, body, opts);
        return;
      }
      if (req.method === 'POST' && path.endsWith('/embeddings')) {
        handleEmbeddings(res, body, opts);
        return;
      }
      if (req.method === 'POST' && path.includes('/telemetry/')) {
        stats.telemetry += 1;
        sendJson(res, 200, {});
        return;
      }
      const stub = ANCILLARY_ROUTES[`${req.method} ${path}`];
      if (stub) {
        stats.ancillary += 1;
        sendJson(res, 200, stub());
        return;
      }
      // Anything else is a route the core reached for that we did not
      // anticipate. Count it loudly — a rising number here means the benchmark
      // is silently exercising a degraded path.
      stats.unknownRoutes += 1;
      process.stderr.write(`[mock-llm] unhandled ${req.method} ${path}\n`);
      sendJson(res, 404, { error: { message: `unhandled route: ${path}` } });
    })
    .catch((err) => {
      stats.malformedRequests += 1;
      if (!res.headersSent) {
        sendJson(res, 400, { error: { message: String(err?.message ?? err) } });
      }
    });
});

// Long agent runs hold connections open; do not let Node time them out mid-turn.
server.keepAliveTimeout = 120_000;
server.headersTimeout = 125_000;

server.listen(opts.port, '127.0.0.1', () => {
  process.stderr.write(
    `[mock-llm] listening on http://127.0.0.1:${opts.port} ` +
      `(latency=${opts.latencyMs}±${opts.jitterMs}ms tool-depth=${opts.toolDepth} ` +
      `reply-chars=${opts.replyChars} fail-rate=${opts.failRate})\n`,
  );
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => {
    server.close(() => process.exit(0));
  });
}
